function e($s): string { return htmlspecialchars((string)$s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function url($page='home', $args=[]): string { return '?' . http_build_query(array_merge(['page'=>$page], $args)); }
function go($page='home', $args=[]): never { header('Location: '.url($page,$args)); exit; }
function csrf(): string { if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32)); return $_SESSION['csrf']; }
function field(): string { return '<input type="hidden" name="csrf" value="'.e(csrf()).'">'; }
function flash($message): void { $_SESSION['flash']=$message; }
function db($callback) {
 $path=dirname(__DIR__).'/storage'; if (!is_dir($path)) mkdir($path,0700,true);
 $fp=fopen($path.'/data.json','c+'); if (!$fp) throw new RuntimeException('Storage unavailable');
 chmod($path.'/data.json',0600); flock($fp, LOCK_EX); $raw=stream_get_contents($fp); $data=$raw ? json_decode($raw,true) : null;
 if (!is_array($data)) $data=['users'=>[], 'orders'=>[], 'attempts'=>[]];
 $result=$callback($data); rewind($fp); ftruncate($fp,0); fwrite($fp,json_encode($data,JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); fflush($fp); flock($fp,LOCK_UN); fclose($fp); return $result;
}
function currentUser() { if (empty($_SESSION['user_id'])) return null; return db(function(&$d) { foreach ($d['users'] as $u) if ($u['id']===$_SESSION['user_id']) return $u; return null; }); }
function cartCount(): int { return array_sum($_SESSION['cart'] ?? []); }
function money($n): string { return '₹'.number_format($n); }
function icon($name): string { $paths=['search'=>'<circle cx="11" cy="11" r="7"/><path d="m16 16 4 4"/>','user'=>'<circle cx="12" cy="8" r="3.5"/><path d="M5 20c0-4 3-6 7-6s7 2 7 6"/>','bag'=>'<path d="M5 8h14l1 12H4L5 8Z"/><path d="M9 9V6a3 3 0 0 1 6 0v3"/>','arrow'=>'<path d="M4 12h16M14 6l6 6-6 6"/>','heart'=>'<path d="M20.8 8.6c0 4-8.8 9.4-8.8 9.4S3.2 12.6 3.2 8.6a4.5 4.5 0 0 1 8.8-1.1 4.5 4.5 0 0 1 8.8 1.1Z"/>']; return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'.($paths[$name]??'').'</svg>'; }
$page=$_GET['page'] ?? 'home'; $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 if (!hash_equals(csrf(), $_POST['csrf'] ?? '')) { http_response_code(403); exit('Invalid request. Please refresh the page and try again.'); }
 $action=$_POST['action'] ?? '';
 if ($action==='add') { $id=$_POST['id']??''; if(isset($books[$id])) { $_SESSION['cart'][$id]=min(20,($_SESSION['cart'][$id]??0)+1); flash('Added to your bag.'); } if (($_POST['return'] ?? '') === 'book') go('book', ['id'=>$id]); header('Location: '.url('home').'#collection'); exit; }
 if ($action==='update_cart') { foreach (($_POST['qty']??[]) as $id=>$qty) if(isset($books[$id],$_SESSION['cart'][$id])) { $n=max(0,min(20,(int)$qty)); if($n===0) unset($_SESSION['cart'][$id]); else $_SESSION['cart'][$id]=$n; } flash('Your bag has been updated.'); go('cart'); }
 if ($action==='logout') { $_SESSION=[]; session_destroy(); session_start(); session_regenerate_id(true); flash('You have signed out.'); go(); }
 if ($action==='register') {
  $name=trim($_POST['name']??''); $email=strtolower(trim($_POST['email']??'')); $password=$_POST['password']??'';
  if(mb_strlen_safe($name)<2 || strlen($name)>100 || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($email)>254 || strlen($password)<10 || strlen($password)>4096) $error='Please enter a valid name and email, and a password of at least 10 characters.';
  else { $result=db(function(&$d) use($name,$email,$password) { foreach($d['users'] as $u) if($u['email']===$email) return false; $id=bin2hex(random_bytes(16)); $d['users'][]=['id'=>$id,'name'=>$name,'email'=>$email,'password'=>password_hash($password,PASSWORD_DEFAULT)]; return $id; }); if(!$result) $error='An account with this email already exists.'; else { session_regenerate_id(true); $_SESSION['user_id']=$result; flash('Welcome to the society.'); go(($_POST['next']??'')==='checkout' ? 'checkout' : 'account'); } }
 }
 if ($action==='login') {
  $email=strtolower(trim($_POST['email']??'')); $password=$_POST['password']??''; $key=hash('sha256',($_SERVER['REMOTE_ADDR']??'unknown').'|'.$email);
  $result=db(function(&$d) use($email,$password,$key) { $now=time(); $d['attempts']=array_filter($d['attempts'],fn($a)=>$a['time']>$now-900); $a=$d['attempts'][$key]??['count'=>0,'time'=>$now]; if($a['count']>=8) return 'locked'; $found=null; foreach($d['users'] as $u) if($u['email']===$email) { $found=$u; break; } if($found && password_verify($password,$found['password'])) { unset($d['attempts'][$key]); return $found['id']; } password_verify($password,'$2y$10$92IXUNpkjO0rOQ5byMi.Ye4oKoEa3Ro9llC/.og/at2uheWG/igi.'); $d['attempts'][$key]=['count'=>$a['count']+1,'time'=>$now]; return false; });
  if($result && $result!=='locked') { session_regenerate_id(true); $_SESSION['user_id']=$result; flash('Welcome back.'); go(($_POST['next']??'')==='checkout' ? 'checkout' : 'account'); } $error=$result==='locked' ? 'Too many attempts. Please try again in 15 minutes.' : 'Email or password not recognised.';
 }
 if ($action==='checkout') {
  $user=currentUser(); if(!$user) go('login'); $cart=$_SESSION['cart']??[]; $address=trim($_POST['address']??''); $phone=trim($_POST['phone']??'');
  if(!$cart) $error='Your bag is empty.'; elseif(strlen($address)<10 || strlen($address)>1000 || !preg_match('/^[0-9+() -]{7,20}$/',$phone)) $error='Please provide a complete delivery address and a valid phone number.';
  else { $items=[]; $total=0; foreach($cart as $id=>$qty) if(isset($books[$id]) && $qty>0) { $b=$books[$id]; $items[]=['title'=>$b['title'],'price'=>$b['price'],'qty'=>$qty]; $total+=$b['price']*$qty; } if(!$items) { $error='Your bag is empty.'; } else { $order=['id'=>strtoupper(bin2hex(random_bytes(4))),'user_id'=>$user['id'],'date'=>date('Y-m-d H:i:s'),'items'=>$items,'total'=>$total,'address'=>$address,'phone'=>$phone,'status'=>'Order request received']; db(function(&$d) use($order){$d['orders'][]=$order;}); $_SESSION['cart']=[]; flash('Your order request has been received. No payment has been taken.'); go('account'); } }
 }
}
